{"content": "package com.example.util;

import java.io.IOException;
import java.io.InputStream;
import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.SQLException;
import java.util.Properties;

/**
 * 数据库工具类 - 简单连接池实现
 */
public class DBUtil {

    private static String url;
    private static String username;
    private static String password;
    private static String driverClass;

    // 简单连接池 - 使用ThreadLocal存储连接
    private static final ThreadLocal<Connection> connectionHolder = new ThreadLocal<>();

    static {
        Properties props = new Properties();
        try {
            InputStream is = DBUtil.class.getClassLoader().getResourceAsStream("db.properties");
            if (is == null) {
                throw new RuntimeException("找不到数据库配置文件 db.properties");
            }
            props.load(is);

            url = props.getProperty("db.url");
            username = props.getProperty("db.username");
            password = props.getProperty("db.password");
            driverClass = props.getProperty("db.driver", "com.mysql.cj.jdbc.Driver");

            Class.forName(driverClass);
            System.out.println("数据库驱动加载成功");
        } catch (IOException | ClassNotFoundException e) {
            throw new RuntimeException("初始化数据库连接失败: " + e.getMessage(), e);
        }
    }

    /**
     * 获取数据库连接
     */
    public static Connection getConnection() {
        Connection conn = connectionHolder.get();
        try {
            if (conn == null || conn.isClosed()) {
                conn = DriverManager.getConnection(url, username, password);
                connectionHolder.set(conn);
            }
        } catch (SQLException e) {
            throw new RuntimeException("获取数据库连接失败: " + e.getMessage(), e);
        }
        return conn;
    }

    /**
     * 开启事务
     */
    public static void beginTransaction() {
        Connection conn = getConnection();
        try {
            conn.setAutoCommit(false);
        } catch (SQLException e) {
            throw new RuntimeException("开启事务失败: " + e.getMessage(), e);
        }
    }

    /**
     * 提交事务
     */
    public static void commit() {
        Connection conn = connectionHolder.get();
        if (conn != null) {
            try {
                conn.commit();
            } catch (SQLException e) {
                throw new RuntimeException("提交事务失败: " + e.getMessage(), e);
            }
        }
    }

    /**
     * 回滚事务
     */
    public static void rollback() {
        Connection conn = connectionHolder.get();
        if (conn != null) {
            try {
                conn.rollback();
            } catch (SQLException e) {
                throw new RuntimeException("回滚事务失败: " + e.getMessage(), e);
            }
        }
    }

    /**
     * 关闭连接
     */
    public static void closeConnection() {
        Connection conn = connectionHolder.get();
        if (conn != null) {
            try {
                conn.setAutoCommit(true);
                conn.close();
            } catch (SQLException e) {
                throw new RuntimeException("关闭连接失败: " + e.getMessage(), e);
            } finally {
                connectionHolder.remove();
            }
        }
    }
